from html.parser import HTMLParser
from pathlib import Path
import re
root = Path('.')
files = [root / 'index.html', *sorted((root / 'pages').glob('*.html'))]
errors = []
class Check(HTMLParser):
    def __init__(self):
        super().__init__(); self.links=[]; self.images=[]; self.title_count=0; self.main_count=0
    def handle_starttag(self, tag, attrs):
        attrs=dict(attrs)
        if tag in ('a','link','script'):
            key = 'href' if tag in ('a','link') else 'src'
            value=attrs.get(key)
            if value and not value.startswith(('https://','http://','mailto:','#','data:')):
                self.links.append(value)
        if tag == 'img': self.images.append(attrs)
        if tag == 'title': self.title_count += 1
        if tag == 'main': self.main_count += 1
for file in files:
    parser=Check(); parser.feed(file.read_text())
    if parser.title_count != 1: errors.append(f'{file}: expected one title')
    if parser.main_count != 1: errors.append(f'{file}: expected one main')
    for image in parser.images:
        if not image.get('alt'): errors.append(f'{file}: image missing alt')
    for target in parser.links:
        path = (file.parent / target.split('#',1)[0]) if not target.startswith('/') else root / target.lstrip('/')
        if target.split('#',1)[0] and not path.exists(): errors.append(f'{file}: missing {target}')
    if 'aria-current="page"' not in file.read_text(): errors.append(f'{file}: no current nav page')
print(f'Checked {len(files)} HTML pages.')
print('\n'.join(errors) if errors else 'Local paths, titles, main landmarks, image alt text, and current navigation links look good.')
if errors: raise SystemExit(1)
