from html.parser import HTMLParser
from pathlib import Path
root = Path('.')
files = [root / 'index.html', *sorted((root / 'pages').glob('*.html'))]
errors = []
class Check(HTMLParser):
    def __init__(self):
        super().__init__(); self.links=[]; self.images=[]; self.title_count=0; self.main_count=0; self.ids=set(); self.fragments=[]
    def handle_starttag(self, tag, attrs):
        attrs=dict(attrs)
        if 'id' in attrs: self.ids.add(attrs['id'])
        if tag in ('a','link','script'):
            key = 'href' if tag in ('a','link') else 'src'
            value=attrs.get(key)
            if value and not value.startswith(('https://','http://','mailto:','data:')):
                self.links.append(value)
                if value.startswith('#'): self.fragments.append(value[1:])
        if tag == 'img': self.images.append(attrs)
        if tag == 'title': self.title_count += 1
        if tag == 'main': self.main_count += 1
for file in files:
    parser=Check(); parser.feed(file.read_text())
    if parser.title_count != 1: errors.append(f'{file}: expected one title')
    if parser.main_count != 1: errors.append(f'{file}: expected one main')
    for image in parser.images:
        if image.get('alt') is None: errors.append(f'{file}: image missing alt attribute')
    for fragment in parser.fragments:
        if fragment not in parser.ids: errors.append(f'{file}: unresolved #{fragment}')
    for target in parser.links:
        target_path, _, fragment = target.partition('#')
        path = (file.parent / target_path) if target_path else file
        if not path.exists(): errors.append(f'{file}: missing {target}')
        elif fragment and target_path:
            linked=Check(); linked.feed(path.read_text())
            if fragment not in linked.ids: errors.append(f'{file}: unresolved {target}')
    if 'aria-current="page"' not in file.read_text(): errors.append(f'{file}: no current nav page')
print(f'Checked {len(files)} HTML pages.')
print('\n'.join(errors) if errors else 'Local paths, page landmarks, image alt attributes, and current navigation links look good.')
if errors: raise SystemExit(1)
