def luminance(color):
    channels=[int(color[i:i+2],16)/255 for i in (1,3,5)]
    values=[c/12.92 if c<=0.04045 else ((c+0.055)/1.055)**2.4 for c in channels]
    return .2126*values[0]+.7152*values[1]+.0722*values[2]
def contrast(foreground, background):
    a,b=sorted((luminance(foreground),luminance(background)),reverse=True)
    return (a+.05)/(b+.05)
for fg,bg,label in [('#B9A9E0','#0B0630','muted/deep'),('#B9A9E0','#2A0A5E','muted/mid'),('#F8F4FF','#0B0630','main/deep'),('#0B0630','#FF2E97','button/pink'),('#0B0630','#FF9E3D','button/orange')]:
